from typing import Any
from typing import TextIO
import csv
import io

import pandas as pd

REQUIRED_COLUMNS = ('name', 'email', 'role')
ALLOWED_ROLES = ('admin', 'editor', 'viewer')
MAX_ROWS = 10000
MAX_EMAIL_LENGTH = 254


# pcat: importers.users_csv.parse@v1
def import_users(source: str | TextIO, max_rows: int=MAX_ROWS) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    reader = csv.DictReader(io.StringIO(source) if isinstance(source, str) else source)
    header = [h.strip().lstrip('\ufeff').lower() for h in reader.fieldnames or []]
    missing = [c for c in REQUIRED_COLUMNS if c not in header]
    if missing:
        return ([], [{'row': 1, 'errors': [f"missing columns: {', '.join(missing)}"]}])
    reader.fieldnames = header
    valid, errors, seen = ([], [], set())
    for count, row in enumerate(reader, 1):
        if count > max_rows:
            stop = f'more than {max_rows} rows; stopped'
            errors.append({'row': reader.line_num, 'errors': [stop]})
            break
        name = (row.get('name') or '').strip()
        email = (row.get('email') or '').strip().lower()
        role = (row.get('role') or '').strip().lower()
        age_raw = (row.get('age') or '').strip()
        local, _, domain = email.partition('@')
        problems = [] if name else ['name is required']
        if None in row:
            problems.append('too many fields')
        if len(email) > MAX_EMAIL_LENGTH or not local or ' ' in email or ('@' in domain) or ('.' not in domain.strip('.')):
            problems.append('email is invalid')
        elif email in seen:
            problems.append('duplicate email')
        if not role:
            problems.append('role is required')
        elif role not in ALLOWED_ROLES:
            problems.append(f"role must be one of: {', '.join(ALLOWED_ROLES)}")
        if age_raw and (not (age_raw.isdigit() and int(age_raw) <= 150)):
            problems.append('age must be a whole number from 0 to 150')
        if problems:
            errors.append({'row': reader.line_num, 'errors': problems})
        else:
            seen.add(email)
            valid.append({'name': name, 'email': email, 'role': role, 'age': int(age_raw) if age_raw else None})
    return (valid, errors)


def validate_user_upload(data: bytes, filename: str, max_rows: int=MAX_ROWS) -> list[dict[str, Any]]:
    """Validate an uploaded users file (.csv or .xlsx).

    Returns a list of {"row": <spreadsheet row number, header = 1>,
    "errors": [<reason>, ...]} for every bad row; an empty list means all rows
    are valid. Every problem on every row is reported, not just the first.
    """
    lowered = filename.lower()
    if lowered.endswith('.xlsx'):
        try:
            frame = pd.read_excel(io.BytesIO(data), dtype=str, keep_default_na=False)
        except Exception:
            return [{'row': 1, 'errors': ['could not read the xlsx file']}]
        text = frame.to_csv(index=False)
    elif lowered.endswith('.csv'):
        try:
            text = data.decode('utf-8-sig')
        except UnicodeDecodeError:
            return [{'row': 1, 'errors': ['csv file must be UTF-8 encoded']}]
    else:
        return [{'row': 1, 'errors': ['unsupported file type; upload a .csv or .xlsx file']}]
    _, errors = import_users(text, max_rows=max_rows)
    return errors


# ---------------------------------------------------------------- tests (pytest)
def _csv(*lines: str) -> bytes:
    return '\n'.join(('name,email,role,age',) + lines).encode('utf-8')


def test_valid_file_has_no_errors():
    data = _csv('Ann,ann@example.com,admin,30', 'Bob,bob@example.com,Viewer,')
    assert validate_user_upload(data, 'users.csv') == []


def test_reports_every_problem_with_row_numbers():
    data = _csv(
        'Ann,ann@example.com,admin,30',   # row 2 ok
        ',not-an-email,boss,abc',         # row 3: four problems
        'Ann Two,ANN@example.com,editor,',  # row 4: duplicate
    )
    errors = validate_user_upload(data, 'users.csv')
    assert [e['row'] for e in errors] == [3, 4]
    assert set(errors[0]['errors']) == {
        'name is required',
        'email is invalid',
        'role must be one of: admin, editor, viewer',
        'age must be a whole number from 0 to 150',
    }
    assert errors[1]['errors'] == ['duplicate email']


def test_missing_required_column():
    errors = validate_user_upload(b'name,email\nAnn,ann@example.com', 'users.csv')
    assert errors == [{'row': 1, 'errors': ['missing columns: role']}]


def test_xlsx_upload(tmp_path):
    pytest = __import__('pytest')
    pytest.importorskip('openpyxl')
    frame = pd.DataFrame(
        {'name': ['Ann', 'Bob'], 'email': ['ann@example.com', 'bad'], 'role': ['admin', 'viewer']}
    )
    path = tmp_path / 'users.xlsx'
    frame.to_excel(path, index=False)
    errors = validate_user_upload(path.read_bytes(), 'users.xlsx')
    assert errors == [{'row': 3, 'errors': ['email is invalid']}]


def test_unsupported_extension():
    errors = validate_user_upload(b'x', 'users.txt')
    assert errors[0]['errors'] == ['unsupported file type; upload a .csv or .xlsx file']

